"""Generate self-contained teaching guides beside each offline demo."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2]
# question, visual key, first action label/selector, comparison label/selector,
# interpretation, optional value for first/comparison action.
def lesson(question,key,first,selector,compare,other,meaning,value=None,other_value=None):
 return dict(question=question,key=key,first=first,selector=selector,compare=compare,other=other,meaning=meaning,value=value,otherValue=other_value)
D={
'PathPlanning':dict(default='search',mount='.experiment-heading',position='after',modes={
'search':lesson('How can we find a route without searching everywhere?','S is the start; G is the destination. Dark cells are walls. Cyan cells are places the search examined; the blue line is its final route.','Run the selected search','#finish','Try Dijkstra on this map','#algorithm','After choosing Dijkstra, use Run to result again. Compare the cyan area and final route cost. On this map, A* uses a goal estimate to guide the search; fewer examined cells does not mean a shorter route.',other_value='dijkstra'),
'replan':lesson('What changes when the robot must plan again?','Blue is the current route. Cyan marks work done during the latest repair, not the robot’s traveled path.','Move the robot one step','#move','Find a place to block the route','#view','Click a blue route cell away from S and G. The route repairs immediately. Compare repair work with a fresh search in the optional results; a large change need not be cheaper to repair.'),
'anyangle':lesson('Must a route follow the grid directions?','Gray is the eight-neighbor A* route. Blue is the selected route. Both use the same obstacles and small circular footprint.','Show the selected route','#finish','Compare eight-neighbor A*','#angle-algorithm','Run to result again. Look for diagonal restrictions versus line-of-sight shortcuts. A geometrically shorter route still does not account for a car’s turning limits.',other_value='astar8'),
'roadmap':lesson('Can we reuse a map of possible connections?','Dots are sampled free positions. Thin lines are collision-free connections. The thick blue route answers the current start-to-goal query.','Build and query the roadmap','#finish','Swap start and destination','#query-swap','The query changes, but the sampled graph stays. A missing route can mean the finite graph missed a connection; it does not prove the physical passage is closed.'),
'sampling':lesson('How can random exploration discover a route?','Cyan branches are accepted connections. The orange dot is the latest random sample. A blue route appears once the tree connects to the goal.','Grow the tree to its result','#finish','Try a tree that improves routes','#sampling-algorithm','Run to result again with RRT*. It continues sampling and rewiring after finding a route. Watch the best-route plot; a finite run need not find the shortest possible path.',other_value='rrtstar'),
'clearance':lesson('Can the whole robot fit through the gap?','Dark cells are obstacles. Orange cells are forbidden robot-center positions. The green disk shows the robot’s radius; blue is a center path.','Show a small robot','#radius','Increase the robot radius','#radius','Compare the orange region and whether a blue path remains. Enlarging obstacles accounts for the robot’s body. This conservative grid may close a gap earlier than exact continuous geometry.',value=.4,other_value=1.5),
'field':lesson('Why can attraction and repulsion get stuck?','The green robot follows the combined force. Short lines show its direction. Dark circles repel it; the purple goal attracts it.','Run the current scene','#finish','Switch to a U-shaped trap','#scene','Run to result again. Look for motion that stalls away from the goal. Local forces do not reason about the complete route around an obstacle.',other_value='trap'),
'local':lesson('How does a route become the next movement?','Blue is the overall route. Faint curves are candidate short motions; orange is the chosen one. Green records where the robot actually went.','Execute one short motion','#step','Try the MPPI sequence controller','#local-algorithm','Use Step or Play to watch repeated decisions. The global route supplies direction; the local controller chooses motion now. The MPPI option samples control sequences. Both use simplified motion and obstacle prediction.',other_value='mppi'),
'imagination':lesson('Can changing orientation make the same passage feasible?','The rectangle is the robot body. All candidate motions use the same center line through the doorway, with different fixed orientations.','Test the candidate orientations','#imagine','Turn the robot across the doorway','#angle','The candidate labels say which complete translations fit. The current pose may be clear before the doorway even when the planned translation collides. This is a geometry illustration, not a reproduction of learned Robot Imagination.',other_value=90),
}),
'SensorFusion':dict(default='arm',mount='.lesson-heading',position='after',modes={
'arm':lesson('Why does one joint move more than one link?','The 3D view shows the linked arm. The frame diagram shows each link’s local axes; a child frame moves with its parent.','Rotate the first joint to 45°','#q0','Rotate it to −45°','#q0','Watch everything attached after the first joint move with it. A link’s local coordinates can stay unchanged while its position in the world changes.',value=45,other_value=-45),
'camera':lesson('What does a longer focal length change?','Compare the 3D scene with the camera image below it. The scene stays fixed while camera settings change its projection.','Double the focal lengths','#zoom','Restore the original camera','#reset','Objects occupy more pixels and less of the scene fits in the image when focal length increases. The camera did not move closer to them.'),
'lidar':lesson('Does a sensor measure every part of an object?','The scene contains objects and discrete LiDAR returns. The range panels show identical targets at different distances.','Use a sparse scan','[data-preset="sparse"]','Use a dense scan','[data-preset="dense"]','Look at the returns describing the same objects. Denser angular sampling can reveal more shape, but the resulting points are measurements, not object recognition.'),
'calibration':lesson('How can known corners reveal camera settings?','Orange marks are observed checkerboard corners; blue rings are predicted positions using the current camera estimate.','Set an incorrect focal length','#fx','Fit the estimate to the corners','#fit','Compare the blue rings with the orange observations before and after fitting. This teaching fit knows the board pose and shares fx and fy; real calibration needs additional views and parameters.',value=1000),
'fusion':lesson('Why do two sensors disagree about one object?','Orange points use the correct alignment; blue points use the estimated alignment. Compare where they land in the camera image.','Introduce an alignment fault','#fault','Restore correct alignment','#reset','The fault changes rotation, translation, and timing together to make disagreement visible. Then use the individual settings to isolate each cause; spatial alignment alone cannot fix a time mismatch.'),
}),
'Localization':dict(default='icp',mount='main > nav',position='after',modes={
'icp':lesson('Where should this scan sit in the known map?','Gray is the known map. Orange is the scan at the estimated pose. Blue is the estimated vehicle pose; the green ring is the true pose for comparison.','Apply one alignment update','#step','Try a poor initial guess','#scenario','Use Step repeatedly after the change. ICP pairs nearby points and adjusts the pose. A plausible alignment may still be wrong when the initial guess makes incorrect pairs.',other_value='far'),
'amcl':lesson('Which possible vehicle locations fit the observations?','Purple arrows are competing pose hypotheses. Blue is the estimate. The green true pose is only a reference for you, not an input to the filter.','Advance one filter stage','#step','Spread hypotheses across the map','#global','Step cycles through motion, measurement, and resampling. After global reinitialization, watch which hypotheses survive. Similar-looking map regions can remain ambiguous.'),
'ndt':lesson('Can regions of map points guide scan alignment?','Gray is the known map; orange is the estimated scan. NDT represents map regions with distributions rather than pairing each scan point with a single map point.','Apply one alignment update','#step','Use larger map cells','#cell','Use Step again. Changing cell size changes the regional representation used for alignment. Larger cells are not automatically more accurate.',other_value='2'),
}),
'Mapping':dict(default='visual',mount='main > nav',position='after',modes={
'visual':lesson('How do repeated image observations become map points?','Left: image features observed across frames. Right: estimated camera trajectory and 3D landmarks. A line in the image is not a road drawn on the map.','Advance one recorded frame','#next','Follow one accepted feature','#select-inlier','Use Next to follow the selected observation. Matching image evidence supports pose and landmark estimates. These tabs replay precomputed estimates; overlay changes do not rerun the estimator.'),
'lidar':lesson('How do separate scans become one map?','Left: the current LiDAR scan. Right: scans placed in a common frame using estimated motion. Matching surfaces link consecutive observations.','Advance one recorded scan','#next','Toggle accumulated map','#accumulate','Turn accumulation off and on to distinguish the current contribution from earlier points. This replay shows local registration; it does not demonstrate automatic loop closure.'),
'challenge':lesson('What can reduce drift over a whole lap?','This tab is simulated. Compare the estimated trajectory with the known reference; it is separate from the recorded camera and LiDAR sequences.','Show the end of the lap','#finish-lap','Toggle GPS position information','#gps-use','Compare the end-of-lap estimate with and without GPS. GPS adds position constraints, while a verified return constraint can address accumulated drift. Biased GPS can also pull the estimate in the wrong direction.'),
}),
'NeuralVision':dict(default='mlp',mount='#drawingPanel .prediction',position='after',modes={
'mlp':lesson('How does an image become a digit prediction?','The drawing becomes a 28 × 28 input. The large digit is the model’s prediction. The cubes show intermediate numerical values.','Load the digit 7','#example','Shift that same digit right','#shift','Compare the prediction before and after the shift. This fully connected network uses fixed input positions. A score is a model output, not proof that the prediction is correct.',value='7'),
'cnn':lesson('What changes when a network uses local image patterns?','Read the predicted digit first. The repeated grids in the 3D view are feature maps produced by local filters.','Load the digit 7','#example','Shift that same digit right','#shift','Compare the same input across networks. Shared filters reuse pattern detectors across positions, but a CNN can still make mistakes after a shift.',value='7'),
 'transformer':lesson('How can image patches use information from one another?','Read the prediction first. The 3D view groups pixels into patch tokens. Attention links relate tokens; moving dots are not a clock of computation.','Load the digit 7','#example','Open layers and attention controls','[data-panel="layers"]','Inspect one attention head after the prediction is clear. Attention describes how this model combines token information; a strong link is not a complete explanation of its decision.',value='7'),
}),
'Control':dict(default='pid',mount='main > .intro',position='after',modes={}),
}
for mode,question,key in [
 ('pid','Why can a vehicle remain slower than its target on a hill?','Compare target speed with actual speed. The controller changes acceleration to close their gap.'),
 ('pure','Where should a vehicle aim to follow a path?','The close-up shows a target ahead on the route. Pure Pursuit steers toward that look-ahead target.'),
 ('stanley','How can sideways distance and heading guide steering?','The close-up relates the front of the vehicle to the route. Both position and heading contribute to the steering decision.'),
 ('lqr','How can a controller balance correction against steering effort?','Compare the vehicle heading and distance from the route. The controller trades tracking errors against control effort.'),
 ('mpc','Why predict several movements before choosing one?','The predicted motion is a possible future. The controller executes only the first steering action, then predicts again.'),
 ('compare','Do different controllers behave the same on one road?','The traces belong to different controllers running the same selected scenario. Compare recovery and steering behavior, not only final position.')]:
 D['Control']['modes'][mode]=lesson(question,key,'Run this case for 20 seconds','#finish','Load the next guided case','#preset','Press Play for the newly selected case. The previous run is kept as a dashed trace when it contains motion. Compare equal run durations; the illustrative tuning is not a ranking of controller families.',other_value='__next__')
D['PathPlanning']['labels']={
 'search':'Search toward a goal · A*', 'replan':'Repair a route · D* Lite',
 'anyangle':'Cut grid corners · Theta*', 'roadmap':'Reuse connections · PRM',
 'sampling':'Explore by sampling · RRT', 'clearance':'Will the robot fit?',
 'field':'Follow forces · potential fields', 'local':'Route versus next motion · MPPI',
 'imagination':'Test a motion before moving'}
TEMPLATE=(Path(__file__).parent/'guide-runtime.js').read_text()
for lab,config in D.items():
 folder=ROOT/'2026/Labs'/lab
 if lab=='NeuralVision':folder=folder/'ws/src/neural_vision_common/web'
 config['lab']=lab
 (folder/'teaching-guide.js').write_text('/* Generated by tools/teaching/build_guides.py. */\n'+TEMPLATE.replace('/*CONFIG*/',json.dumps(config,ensure_ascii=False)))
 p=folder/'index.html';text=p.read_text()
 if 'src="teaching-guide.js"' not in text:text=text.replace('</body>','<script defer src="teaching-guide.js"></script></body>')
 p.write_text(text)
print('Generated guides for six collections and',sum(len(c['modes']) for c in D.values()),'experiment modes')
